using Zenject;
using UnityEngine;

public class GameInstaller : MonoInstaller
{
    [SerializeField] private PlayerController playerPrefab;
    [SerializeField] private EnemyFactory enemyFactory;
    [SerializeField] private AudioManager audioManager;

    public override void InstallBindings()
    {
        Container.Bind<IGameStateService>()
            .To<GameStateManager>()
            .AsSingle();

        Container.Bind<IAudioService>()
            .To<AudioManager>()
            .FromInstance(audioManager)
            .AsSingle();

        Container.Bind<IAnalyticsService>()
            .To<AnalyticsManager>()
            .AsSingle()
            .NonLazy();

        Container.BindFactory<Vector3, EnemyType, EnemyController, EnemyController.Factory>()
            .FromPoolableMemoryPool<Vector3, EnemyType, EnemyController, EnemyPool>(
                poolBinder => poolBinder
                    .WithInitialSize(50)
                    .FromComponentInNewPrefab(enemyFactory.enemyPrefab)
                    .UnderTransformGroup("Enemies"));

        Container.Bind<IPlayerController>()
            .To<PlayerController>()
            .FromComponentInNewPrefab(playerPrefab)
            .AsSingle()
            .WithGameObjectName("Player");
    }
}

public class EnemyController : MonoBehaviour, IPoolable<Vector3, EnemyType, IMemoryPool>
{
    [Inject] private IGameStateService gameState;
    [Inject] private IAudioService audio;
    [InjectOptional] private IAnalyticsService analytics;

    private EnemyType enemyType;
    private IMemoryPool pool;
    private AudioClip spawnSound;

    [Inject]
    public void Construct(EnemyData data, [Inject(Id = "SpawnSFX")] AudioClip spawnSound)
    {
        this.spawnSound = spawnSound;
    }

    public void OnSpawned(Vector3 position, EnemyType type, IMemoryPool pool)
    {
        this.enemyType = type;
        this.pool = pool;
        transform.position = position;
        gameState.RegisterEnemy(this);
        audio.PlaySFX(spawnSound);
        analytics?.TrackEnemySpawned(type);
    }

    public void OnDespawned()
    {
        gameState.UnregisterEnemy(this);
        pool.Despawn(this);
    }

    public void Die()
    {
        pool.Despawn(this);
    }

    public class Factory : PlaceholderFactory<Vector3, EnemyType, EnemyController> { }
}

