}

public class MoveEntityCommand : ICommand
{
    private readonly Transform target;
    private readonly Vector3 fromPosition;
    private readonly Vector3 toPosition;
    private readonly float timestamp;

    public string Description => $"Move {target.name} to {toPosition}";
    public float Timestamp => timestamp;

    public MoveEntityCommand(Transform target, Vector3 toPosition)
    {
        this.target = target;
        this.fromPosition = target.position;
        this.toPosition = toPosition;
        this.timestamp = Time.time;
    }

    public void Execute() => target.position = toPosition;
    public void Undo() => target.position = fromPosition;
}

public class DamageEntityCommand : ICommand
{
    private readonly IDamageable target;
    private readonly int damageAmount;
    private readonly float timestamp;
    private int previousHealth;

    public string Description => $"Deal {damageAmount} damage to {target}";
    public float Timestamp => timestamp;

    public DamageEntityCommand(IDamageable target, int damage)
    {
        this.target = target;
        this.damageAmount = damage;
        this.timestamp = Time.time;
    }

    public void Execute()
    {
        previousHealth = target.CurrentHealth;
        target.TakeDamage(damageAmount);
    }

    public void Undo()
    {
        target.SetHealth(previousHealth);
    }
}

