public class CommandHistory : MonoBehaviour
{
    [SerializeField] private int maxHistorySize = 1000;
    [SerializeField] private bool logCommands = true;

    private readonly LinkedList<ICommand> history = new();
    private LinkedListNode<ICommand> currentNode;

    public event Action<ICommand> OnCommandExecuted;
    public event Action<ICommand> OnCommandUndone;
    public event Action<ICommand> OnCommandRedone;

    public bool CanUndo => currentNode != null;
    public bool CanRedo => currentNode?.Next != null;
    public int HistoryCount => history.Count;

    public void Execute(ICommand command)
    {
        if (currentNode != null && currentNode.Next != null)
        {
            var nodeToRemove = currentNode.Next;
            while (nodeToRemove != null)
            {
                var next = nodeToRemove.Next;
                history.Remove(nodeToRemove);
                nodeToRemove = next;
            }
        }

        command.Execute();
        history.AddLast(command);
        currentNode = history.Last;

        while (history.Count > maxHistorySize)
        {
            history.RemoveFirst();
        }

        if (logCommands)
            Debug.Log($"[CMD] Executed: {command.Description}");

        OnCommandExecuted?.Invoke(command);
    }

    public void Undo()
    {
        if (!CanUndo) return;

        currentNode.Value.Undo();
        if (logCommands)
            Debug.Log($"[CMD] Undone: {currentNode.Value.Description}");

        var undoneCommand = currentNode.Value;
        currentNode = currentNode.Previous;
        OnCommandUndone?.Invoke(undoneCommand);
    }

    public void Redo()
    {
        if (!CanRedo) return;

        currentNode = currentNode.Next ?? history.First;
        currentNode.Value.Execute();
        if (logCommands)
            Debug.Log($"[CMD] Redone: {currentNode.Value.Description}");

        OnCommandRedone?.Invoke(currentNode.Value);
    }

    public void Clear()
    {
        history.Clear();
        currentNode = null;
    }

    public IEnumerable<ICommand> GetHistorySnapshot()
    {
        return new List<ICommand>(history);
    }
}

public class MacroCommand : ICommand
{
    private readonly List<ICommand> commands = new();
    private readonly string name;
    private readonly float timestamp;

    public string Description => $"Macro: {name} ({commands.Count} commands)";
    public float Timestamp => timestamp;

    public MacroCommand(string name)
    {
        this.name = name;
        this.timestamp = Time.time;
    }

    public void Add(ICommand command) => commands.Add(command);

    public void Execute()
    {
        foreach (var cmd in commands)
            cmd.Execute();
    }

    public void Undo()
    {
        for (int i = commands.Count - 1; i >= 0; i--)
            commands[i].Undo();
    }
}

public class LevelEditorController : MonoBehaviour
{
    [SerializeField] private CommandHistory history;
    [SerializeField] private GameObject selectedPrefab;

    void Update()
    {
        if (Input.GetMouseButtonDown(0) && selectedPrefab != null)
        {
            Ray ray = Camera.main.ScreenPointToRay(Input.mousePosition);
            if (Physics.Raycast(ray, out RaycastHit hit))
            {
                var cmd = new SpawnEntityCommand(selectedPrefab, hit.point, Quaternion.identity, null);
                history.Execute(cmd);
            }
        }

        if (Input.GetKey(KeyCode.LeftControl) && Input.GetKeyDown(KeyCode.Z))
            history.Undo();

        if (Input.GetKey(KeyCode.LeftControl) && Input.GetKeyDown(KeyCode.Y))
            history.Redo();
    }
}

using UniRx;
using UnityEngine;
using System;

public class ReactiveHealthSystem : MonoBehaviour
{
    public ReactiveProperty<int> Health { get; private set; } = new ReactiveProperty<int>(100);
    public ReactiveProperty<int> MaxHealth { get; private set; } = new ReactiveProperty<int>(100);

    public IReadOnlyReactiveProperty<float> HealthPercent =>
        Health.CombineLatest(MaxHealth, (h, max) => (float)h / max)
              .ToReactiveProperty();

    private readonly Subject<int> onDamaged = new Subject<int>();
    public IObservable<int> OnDamaged => onDamaged;

    private readonly AsyncSubject<Unit> onDeath = new AsyncSubject<Unit>();
    public IObservable<Unit> OnDeath => onDeath;

    void Start()
    {
        HealthPercent
            .Throttle(TimeSpan.FromMilliseconds(16))
            .Subscribe(percent =>
            {
                UIManager.Instance.UpdateHealthBar(percent);
            })
            .AddTo(this);

        Health
            .Where(h => h > 0 && h < 20)
            .ThrottleFirst(TimeSpan.FromSeconds(2))
            .Subscribe(_ =>
            {
                UIManager.Instance.ShowWarning("Low Health!");
            })
            .AddTo(this);

        Health
            .Where(h => h <= 0)
            .Take(1)
            .Subscribe(_ =>
            {
                onDeath.OnNext(Unit.Default);
                onDeath.OnCompleted();
                Die();
            })
            .AddTo(this);

        Observable.EveryUpdate()
            .Where(_ => Input.GetKeyDown(KeyCode.Space))
            .WithLatestFrom(Health, (_, h) => h)
            .Where(h => h > 0)
            .Subscribe(_ => Jump())
            .AddTo(this);
    }

    public void TakeDamage(int damage)
    {
        Health.Value = Mathf.Max(0, Health.Value - damage);
        onDamaged.OnNext(damage);
    }

    public void Heal(int amount)
    {
        Health.Value = Mathf.Min(MaxHealth.Value, Health.Value + amount);
    }

    void Die() { }
    void Jump() { }
}

