using UniRx;
using UnityEngine;
using System;
using System.Collections.Generic;

public class ReactiveGameState : MonoBehaviour
{
    public ReactiveProperty<int> Score { get; } = new ReactiveProperty<int>(0);

    private readonly Subject<Unit> onKill = new Subject<Unit>();
    public IObservable<int> ComboCount => onKill
        .Buffer(onKill.Throttle(TimeSpan.FromSeconds(2)))
        .Select(kills => kills.Count)
        .Where(count => count > 1);

    private readonly Dictionary<string, ReactiveProperty<bool>> achievements = new();

    void Start()
    {
        Score
            .Throttle(TimeSpan.FromSeconds(1))
            .Subscribe(score => SaveSystem.SaveScore(score))
            .AddTo(this);

        ComboCount
            .Subscribe(combo =>
            {
                UIManager.Instance.ShowComboText($"{combo}x COMBO!");
            })
            .AddTo(this);

        Observable.Merge(
            Score.Where(s => s >= 1000).Select(_ => "Score1000"),
            onKill.Buffer(TimeSpan.FromSeconds(5)).Where(k => k.Count >= 10).Select(_ => "KillingSpree")
        )
        .Distinct()
        .Subscribe(achievementId => UnlockAchievement(achievementId))
        .AddTo(this);

        Observable.EveryUpdate()
            .Buffer(TimeSpan.FromSeconds(1))
            .Select(frames => frames.Count)
            .Subscribe(fps => Debug.Log($"FPS: {fps}"))
            .AddTo(this);
    }

    public void AddKill() => onKill.OnNext(Unit.Default);
    public void AddScore(int points) => Score.Value += points;

    void UnlockAchievement(string id)
    {
        if (!achievements.ContainsKey(id))
            achievements[id] = new ReactiveProperty<bool>(false);
        achievements[id].Value = true;
        Debug.Log($"Achievement unlocked: {id}");
    }
}

