[BurstCompile]
public partial struct DamageSystem : ISystem
{
    [BurstCompile]
    public void OnUpdate(ref SystemState state)
    {
        var ecb = new EntityCommandBuffer(Allocator.Temp);

        foreach (var (health, entity) in
            SystemAPI.Query<RefRW<Health>>().WithEntityAccess())
        {
            if (health.ValueRO.Current <= 0)
            {
                ecb.SetComponentEnabled<Health>(entity, false);
                ecb.AddComponent<IsDeadTag>(entity);
            }
        }

        ecb.Playback(state.EntityManager);
        ecb.Dispose();
    }
}

public struct IsDeadTag : IComponentData { }

[BurstCompile]
public partial struct ChunkIterationSystem : ISystem
{
    [BurstCompile]
    public void OnUpdate(ref SystemState state)
    {
        var query = SystemAPI.QueryBuilder()
            .WithAll<LocalTransform, Velocity, Health>()
            .WithNone<IsDeadTag>()
            .Build();

        var chunks = query.ToArchetypeChunkArray(Allocator.Temp);

        var transformType = SystemAPI.GetComponentTypeHandle<LocalTransform>(false);
        var velocityType = SystemAPI.GetComponentTypeHandle<Velocity>(true);
        var healthType = SystemAPI.GetComponentTypeHandle<Health>(false);

        float deltaTime = SystemAPI.Time.DeltaTime;

        foreach (var chunk in chunks)
        {
            var transforms = chunk.GetNativeArray(ref transformType);
            var velocities = chunk.GetNativeArray(ref velocityType);
            var healths = chunk.GetNativeArray(ref healthType);

            for (int i = 0; i < chunk.Count; i++)
            {
                var transform = transforms[i];
                var velocity = velocities[i];
                var health = healths[i];

                transform.Position += velocity.Value * deltaTime;
                health.Current -= deltaTime * 0.1f;

                transforms[i] = transform;
                healths[i] = health;
            }
        }

        chunks.Dispose();
    }
}

