}

[UpdateInGroup(typeof(PhysicsSystemGroup))]
[UpdateAfter(typeof(PhysicsSimulationGroup))]
public partial struct CollisionEventSystem : ISystem
{
    [BurstCompile]
    public void OnUpdate(ref SystemState state)
    {
        var physicsWorld = SystemAPI.GetSingleton<PhysicsWorldSingleton>();
        var collisionEvents = physicsWorld.Simulation.CollisionEvents;

        foreach (var collisionEvent in collisionEvents)
        {
            Entity entityA = collisionEvent.EntityA;
            Entity entityB = collisionEvent.EntityB;

            if (SystemAPI.HasComponent<DamageOnCollision>(entityA))
            {
                ApplyDamage(entityB, SystemAPI.GetComponent<DamageOnCollision>(entityA).Damage);
            }
            if (SystemAPI.HasComponent<DamageOnCollision>(entityB))
            {
                ApplyDamage(entityA, SystemAPI.GetComponent<DamageOnCollision>(entityB).Damage);
            }
        }
    }

    void ApplyDamage(Entity target, float damage)
    {
        if (SystemAPI.HasComponent<Health>(target))
        {
            var health = SystemAPI.GetComponentRW<Health>(target);
            health.ValueRW.Current -= damage;
        }
    }
}

