public class CustomRenderPipeline : RenderPipeline
{
    private bool useDynamicBatching;
    private bool useGPUInstancing;
    private bool useSRPBatcher;
    private ShadowSettings shadowSettings;
    private CustomRenderPasses renderPasses;

    public CustomRenderPipeline(bool dynamicBatching, bool gpuInstancing, bool srpBatcher, ShadowSettings shadows)
    {
        this.useDynamicBatching = dynamicBatching;
        this.useGPUInstancing = gpuInstancing;
        this.useSRPBatcher = srpBatcher;
        this.shadowSettings = shadows;
        this.renderPasses = new CustomRenderPasses();

        GraphicsSettings.useScriptableRenderPipelineBatching = srpBatcher;
    }

    protected override void Render(ScriptableRenderContext context, Camera[] cameras)
    {
        foreach (Camera camera in cameras)
        {
            RenderCamera(context, camera);
        }
    }

    void RenderCamera(ScriptableRenderContext context, Camera camera)
    {
        // Culling
        ScriptableCullingParameters cullingParams;
        if (!camera.TryGetCullingParameters(out cullingParams))
            return;

        CullingResults cullingResults = context.Cull(ref cullingParams);

        // Setup camera properties (view, projection, etc.)
        context.SetupCameraProperties(camera);

        // Clear render target
        CommandBuffer cmd = new CommandBuffer { name = camera.name };
        CameraClearFlags clearFlags = camera.clearFlags;
        cmd.ClearRenderTarget(
            clearFlags <= CameraClearFlags.Depth,
            clearFlags == CameraClearFlags.Color,
            clearFlags == CameraClearFlags.Color ? camera.backgroundColor.linear : Color.clear
        );
        context.ExecuteCommandBuffer(cmd);
        cmd.Clear();

        // Draw opaque objects
        SortingSettings sortingSettings = new SortingSettings(camera) { criteria = SortingCriteria.CommonOpaque };
        DrawingSettings drawingSettings = new DrawingSettings(new ShaderTagId("SRPDefaultUnlit"), sortingSettings)
        {
            enableDynamicBatching = useDynamicBatching,
            enableInstancing = useGPUInstancing
        };
        FilteringSettings filteringSettings = new FilteringSettings(RenderQueueRange.opaque);

        context.DrawRenderers(cullingResults, ref drawingSettings, ref filteringSettings);

        // Draw skybox
        if (camera.clearFlags == CameraClearFlags.Skybox && RenderSettings.skybox != null)
        {
            context.DrawSkybox(camera);
        }

        // Draw transparent objects
        sortingSettings.criteria = SortingCriteria.CommonTransparent;
        drawingSettings.sortingSettings = sortingSettings;
        filteringSettings.renderQueueRange = RenderQueueRange.transparent;
        context.DrawRenderers(cullingResults, ref drawingSettings, ref filteringSettings);

        // Submit
        context.Submit();
    }
}

