public class OutlinePass : ScriptableRenderPass
{
    private Material outlineMaterial;
    private RenderTargetIdentifier source;
    private RenderTargetHandle tempTexture;

    public float OutlineWidth { get; set; } = 1f;
    public Color OutlineColor { get; set; } = Color.black;

    public OutlinePass(RenderPassEvent renderPassEvent, Material material)
    {
        this.renderPassEvent = renderPassEvent;
        this.outlineMaterial = material;
        tempTexture.Init("_OutlineTempTexture");
    }

    public override void Execute(ScriptableRenderContext context, ref RenderingData renderingData)
    {
        CommandBuffer cmd = CommandBufferPool.Get("Outline Pass");

        RenderTextureDescriptor descriptor = renderingData.cameraData.cameraTargetDescriptor;
        descriptor.depthBufferBits = 0;

        cmd.GetTemporaryRT(tempTexture.id, descriptor, FilterMode.Bilinear);

        // Set shader properties
        outlineMaterial.SetFloat("_OutlineWidth", OutlineWidth);
        outlineMaterial.SetColor("_OutlineColor", OutlineColor);

        // Blit from camera target to temp texture with outline material
        source = renderingData.cameraData.renderer.cameraColorTarget;
        cmd.Blit(source, tempTexture.Identifier(), outlineMaterial);
        cmd.Blit(tempTexture.Identifier(), source);

        context.ExecuteCommandBuffer(cmd);
        CommandBufferPool.Release(cmd);
    }

    public override void FrameCleanup(CommandBuffer cmd)
    {
        cmd.ReleaseTemporaryRT(tempTexture.id);
    }
}

