public class GPUParticleSystem : MonoBehaviour
{
    [SerializeField] private ComputeShader particleCompute;
    [SerializeField] private Material particleMaterial;
    [SerializeField] private Mesh particleMesh;
    [SerializeField] private int maxParticles = 100000;
    [SerializeField] private float spawnRate = 1000f;

    private ComputeBuffer positionBuffer;
    private ComputeBuffer velocityBuffer;
    private ComputeBuffer lifeBuffer;
    private ComputeBuffer argsBuffer;
    private int kernelUpdate;
    private int kernelSpawn;
    private float spawnAccumulator;
    private Bounds bounds;

    struct ParticleData
    {
        public Vector3 position;
        public Vector3 velocity;
        public float life;
        public float maxLife;
        public float size;
        public Color color;
    }

    void Start()
    {
        kernelUpdate = particleCompute.FindKernel("CSUpdate");
        kernelSpawn = particleCompute.FindKernel("CSSpawn");

        int stride = System.Runtime.InteropServices.Marshal.SizeOf(typeof(ParticleData));
        positionBuffer = new ComputeBuffer(maxParticles, stride);
        velocityBuffer = new ComputeBuffer(maxParticles, sizeof(float) * 3);
        lifeBuffer = new ComputeBuffer(maxParticles, sizeof(float) * 2);

        // Indirect draw args
        argsBuffer = new ComputeBuffer(1, sizeof(uint) * 5, ComputeBufferType.IndirectArguments);
        uint[] args = new uint[5] { particleMesh.GetIndexCount(0), (uint)maxParticles, 0, 0, 0 };
        argsBuffer.SetData(args);

        bounds = new Bounds(Vector3.zero, Vector3.one * 1000f);

        // Initialize particle material
        particleMaterial.SetBuffer("_PositionBuffer", positionBuffer);
        particleMaterial.SetBuffer("_LifeBuffer", lifeBuffer);
    }

    void Update()
    {
        spawnAccumulator += spawnRate * Time.deltaTime;
        int spawnCount = Mathf.Min((int)spawnAccumulator, maxParticles);
        spawnAccumulator -= spawnCount;

        if (spawnCount > 0)
        {
            particleCompute.SetInt("_SpawnCount", spawnCount);
            particleCompute.SetFloat("_Time", Time.time);
            particleCompute.SetVector("_SpawnPosition", transform.position);
            particleCompute.SetBuffer(kernelSpawn, "_PositionBuffer", positionBuffer);
            particleCompute.SetBuffer(kernelSpawn, "_VelocityBuffer", velocityBuffer);
            particleCompute.SetBuffer(kernelSpawn, "_LifeBuffer", lifeBuffer);
            particleCompute.Dispatch(kernelSpawn, Mathf.CeilToInt(spawnCount / 64f), 1, 1);
        }

        // Update all particles
        particleCompute.SetFloat("_DeltaTime", Time.deltaTime);
        particleCompute.SetFloat("_Time", Time.time);
        particleCompute.SetVector("_Gravity", Physics.gravity);
        particleCompute.SetBuffer(kernelUpdate, "_PositionBuffer", positionBuffer);
        particleCompute.SetBuffer(kernelUpdate, "_VelocityBuffer", velocityBuffer);
        particleCompute.SetBuffer(kernelUpdate, "_LifeBuffer", lifeBuffer);
        particleCompute.Dispatch(kernelUpdate, Mathf.CeilToInt(maxParticles / 64f), 1, 1);
    }

    void OnRenderObject()
    {
        particleMaterial.SetPass(0);
        Graphics.DrawMeshInstancedIndirect(particleMesh, 0, particleMaterial, bounds, argsBuffer);
    }

    void OnDestroy()
    {
        positionBuffer?.Release();
        velocityBuffer?.Release();
        lifeBuffer?.Release();
        argsBuffer?.Release();
    }
}

