public class GPUCullingSystem : MonoBehaviour
{
    [SerializeField] private ComputeShader cullingCompute;
    [SerializeField] private Mesh[] lodMeshes;
    [SerializeField] private Material renderMaterial;
    [SerializeField] private int maxInstances = 50000;

    private ComputeBuffer instanceDataBuffer;
    private ComputeBuffer visibleInstanceBuffer;
    private ComputeBuffer drawArgsBuffer;
    private ComputeBuffer countBuffer;
    private int kernelCulling;
    private Bounds worldBounds;

    struct InstanceData
    {
        public Matrix4x4 matrix;
        public Vector3 boundsCenter;
        public Vector3 boundsExtents;
        public float distance;
        public int lodLevel;
    }

    void Start()
    {
        kernelCulling = cullingCompute.FindKernel("CSFrustumCull");

        int stride = Marshal.SizeOf(typeof(InstanceData));
        instanceDataBuffer = new ComputeBuffer(maxInstances, stride);
        visibleInstanceBuffer = new ComputeBuffer(maxInstances, stride);
        countBuffer = new ComputeBuffer(1, sizeof(uint), ComputeBufferType.Raw);

        // Draw args for each LOD
        drawArgsBuffer = new ComputeBuffer(lodMeshes.Length, sizeof(uint) * 5, ComputeBufferType.IndirectArguments);

        worldBounds = new Bounds(Vector3.zero, Vector3.one * 10000f);
    }

    void Update()
    {
        // Upload camera frustum planes to GPU
        Plane[] frustumPlanes = GeometryUtility.CalculateFrustumPlanes(Camera.main);
        Vector4[] planes = new Vector4[6];
        for (int i = 0; i < 6; i++)
        {
            planes[i] = new Vector4(
                frustumPlanes[i].normal.x,
                frustumPlanes[i].normal.y,
                frustumPlanes[i].normal.z,
                frustumPlanes[i].distance
            );
        }

        cullingCompute.SetVectorArray("_FrustumPlanes", planes);
        cullingCompute.SetVector("_CameraPosition", Camera.main.transform.position);
        cullingCompute.SetFloats("_LodDistances", new float[] { 50f, 150f, 300f, 600f });
        cullingCompute.SetBuffer(kernelCulling, "_InstanceData", instanceDataBuffer);
        cullingCompute.SetBuffer(kernelCulling, "_VisibleInstances", visibleInstanceBuffer);
        cullingCompute.SetBuffer(kernelCulling, "_VisibleCount", countBuffer);

        // Reset counter
        uint[] resetCount = new uint[] { 0 };
        countBuffer.SetData(resetCount);

        // Run culling on GPU
        cullingCompute.Dispatch(kernelCulling, Mathf.CeilToInt(maxInstances / 64f), 1, 1);

        // Read back visible count (async)
        uint[] visibleCount = new uint[1];
        countBuffer.GetData(visibleCount);

        // Update draw args
        for (int i = 0; i < lodMeshes.Length; i++)
        {
            uint[] args = new uint[5];
            args[0] = lodMeshes[i].GetIndexCount(0);
            args[1] = visibleCount[0]; // Simplified — in production, count per LOD
            args[2] = lodMeshes[i].GetIndexStart(0);
            args[3] = lodMeshes[i].GetBaseVertex(0);
            args[4] = 0;

            drawArgsBuffer.SetData(args, 0, i * 5, 5);
        }
    }

    void OnRenderObject()
    {
        renderMaterial.SetBuffer("_InstanceData", visibleInstanceBuffer);
        renderMaterial.SetPass(0);

        for (int i = 0; i < lodMeshes.Length; i++)
        {
            Graphics.DrawMeshInstancedIndirect(
                lodMeshes[i],
                0,
                renderMaterial,
                worldBounds,
                drawArgsBuffer,
                i * 5 * sizeof(uint)
            );
        }
    }

    void OnDestroy()
    {
        instanceDataBuffer?.Release();
        visibleInstanceBuffer?.Release();
        drawArgsBuffer?.Release();
        countBuffer?.Release();
    }
}

