[Title("Custom", "World Space Curve")]
public class WorldSpaceCurveNode : CodeFunctionNode
{
    public WorldSpaceCurveNode()
    {
        name = "World Space Curve";
    }

    protected override MethodInfo GetFunctionToConvert()
    {
        return GetType().GetMethod("WorldSpaceCurveFunction", BindingFlags.Static | BindingFlags.NonPublic);
    }

    static string WorldSpaceCurveFunction(
        [Slot(0, Binding.MeshUV0)] Vector2 UV,
        [Slot(1, Binding.None)] Vector1 CurveStrength,
        [Slot(2, Binding.None)] Vector1 CurveFrequency,
        [Slot(3, Binding.None)] Vector1 CurveOffset,
        [Slot(4, Binding.ObjectSpacePosition)] Vector3 ObjectPosition,
        [Slot(5)] out Vector3 OutPosition,
        [Slot(6)] out Vector3 OutNormal)
    {
        OutPosition = ObjectPosition;
        OutNormal = Vector3.zero;
        return @"{
            float3 worldPos = TransformObjectToWorld(ObjectPosition);
            float curve = sin(worldPos.x * CurveFrequency + CurveOffset) * CurveStrength;
            worldPos.y += curve;
            OutPosition = TransformWorldToObject(worldPos);

            float3 tangent = normalize(float3(1.0, CurveStrength * CurveFrequency * cos(worldPos.x * CurveFrequency + CurveOffset), 0.0));
            float3 normal = float3(-tangent.y, tangent.x, 0.0);
            OutNormal = TransformWorldToObjectNormal(normal);
        }";
    }
}

