// LOD CROSSFADE CONTROLLER
// ============================================
public class LODCrossfadeController : MonoBehaviour
{
    [SerializeField] private float crossfadeDuration = 0.5f;
    [SerializeField] private AnimationCurve crossfadeCurve = AnimationCurve.EaseInOut(0, 0, 1, 1);

    private MaterialPropertyBlock propertyBlock;
    private Renderer[] renderers;
    private float currentFade;
    private int targetLOD;
    private int currentLOD;
    private bool isTransitioning;

    void Start()
    {
        propertyBlock = new MaterialPropertyBlock();
        renderers = GetComponentsInChildren<Renderer>();
    }

    public void TransitionToLOD(int lodLevel)
    {
        if (lodLevel == currentLOD || isTransitioning) return;
        targetLOD = lodLevel;
        isTransitioning = true;
        StartCoroutine(CrossfadeCoroutine());
    }

    System.Collections.IEnumerator CrossfadeCoroutine()
    {
        float elapsed = 0f;

        // Enable both LODs during transition
        SetLODActive(currentLOD, true);
        SetLODActive(targetLOD, true);

        while (elapsed < crossfadeDuration)
        {
            elapsed += Time.deltaTime;
            float t = crossfadeCurve.Evaluate(elapsed / crossfadeDuration);

            // Fade out current LOD
            SetLODFade(currentLOD, 1f - t);
            // Fade in target LOD
            SetLODFade(targetLOD, t);

            yield return null;
        }

        // Finalize
        SetLODFade(currentLOD, 0f);
        SetLODFade(targetLOD, 1f);
        SetLODActive(currentLOD, false);
        currentLOD = targetLOD;
        isTransitioning = false;
    }

    void SetLODActive(int lod, bool active)
    {
        // Implementation depends on your LOD group setup
        // Typically: enable/disable renderer or swap mesh/material
    }

    void SetLODFade(int lod, float fade)
    {
        foreach (var renderer in renderers)
        {
            renderer.GetPropertyBlock(propertyBlock);
            propertyBlock.SetFloat("_LODFade", fade);
            propertyBlock.SetFloat("_DitherScale", fade > 0.5f ? 1f : 0.5f);
            renderer.SetPropertyBlock(propertyBlock);
        }
    }
}

