// ============================================
// VERTEX DISPLACEMENT SHADER (Waves)
// ============================================
Shader "Custom/VertexDisplacementWave"
{
    Properties
    {
        _BaseColor ("Base Color", Color) = (0.2, 0.4, 0.8, 1)
        _WaveSpeed ("Wave Speed", Float) = 1.0
        _WaveAmplitude ("Wave Amplitude", Float) = 0.5
        _WaveFrequency ("Wave Frequency", Float) = 2.0
        _NormalStrength ("Normal Strength", Float) = 1.0
    }
    SubShader
    {
        Tags { "RenderType"="Opaque" "RenderPipeline"="UniversalPipeline" }
        LOD 300

        Pass
        {
            Name "ForwardLit"
            Tags { "LightMode"="UniversalForward" }

            HLSLPROGRAM
            #pragma vertex vert
            #pragma fragment frag
            #pragma multi_compile _ _MAIN_LIGHT_SHADOWS
            #pragma multi_compile _ _ADDITIONAL_LIGHTS

            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Core.hlsl"
            #include "Packages/com.unity.render-pipelines.universal/ShaderLibrary/Lighting.hlsl"

            struct Attributes
            {
                float4 positionOS : POSITION;
                float3 normalOS : NORMAL;
                float2 uv : TEXCOORD0;
            };

            struct Varyings
            {
                float4 positionCS : SV_POSITION;
                float3 positionWS : TEXCOORD0;
                float3 normalWS : TEXCOORD1;
                float2 uv : TEXCOORD2;
            };

            CBUFFER_START(UnityPerMaterial)
                float4 _BaseColor;
                float _WaveSpeed;
                float _WaveAmplitude;
                float _WaveFrequency;
                float _NormalStrength;
            CBUFFER_END

            float3 GerstnerWave(float3 position, float2 direction, float steepness, float wavelength, float speed, float time)
            {
                float k = 2 * PI / wavelength;
                float c = sqrt(9.8 / k) * speed;
                float2 d = normalize(direction);
                float f = k * (dot(d, position.xz) - c * time);
                float a = steepness / k;

                float3 displacement;
                displacement.x = d.x * (a * cos(f));
                displacement.y = a * sin(f);
                displacement.z = d.y * (a * cos(f));

                return displacement;
            }

            Varyings vert(Attributes input)
            {
                Varyings output;

                float3 positionWS = TransformObjectToWorld(input.positionOS.xyz);
                float time = _Time.y * _WaveSpeed;

                // Apply Gerstner waves
                float3 displacement = GerstnerWave(positionWS, float2(1, 0), 0.5, _WaveFrequency, 1.0, time);
                displacement += GerstnerWave(positionWS, float2(0.5, 0.5), 0.3, _WaveFrequency * 0.8, 1.2, time);
                displacement += GerstnerWave(positionWS, float2(-0.3, 0.7), 0.2, _WaveFrequency * 1.5, 0.8, time);

                positionWS += displacement * _WaveAmplitude;

                // Recalculate normal from displacement
                float3 tangent = float3(1, 0, 0);
                float3 bitangent = float3(0, 0, 1);
                float3 normalWS = normalize(cross(tangent, bitangent));

                output.positionCS = TransformWorldToHClip(positionWS);
                output.positionWS = positionWS;
                output.normalWS = normalWS;
                output.uv = input.uv;

                return output;
            }

            float4 frag(Varyings input) : SV_Target
            {
                #if defined(_MAIN_LIGHT_SHADOWS)
                float4 shadowCoord = TransformWorldToShadowCoord(input.positionWS);
                float shadowAttenuation = MainLightRealtimeShadow(shadowCoord);
                #else
                float shadowAttenuation = 1.0;
                #endif

                float3 normalWS = normalize(input.normalWS);
                float3 lightDir = normalize(_MainLightPosition.xyz);
                float NdotL = saturate(dot(normalWS, lightDir));

                float3 color = _BaseColor.rgb * NdotL * shadowAttenuation;
                color += _BaseColor.rgb * 0.1; // Ambient

                // Fresnel for water edge
                float3 viewDir = normalize(_WorldSpaceCameraPos - input.positionWS);
                float fresnel = pow(1.0 - saturate(dot(viewDir, normalWS)), 3.0);
                color = lerp(color, float3(0.8, 0.9, 1.0), fresnel * 0.5);

                return float4(color, 1.0);
            }
            ENDHLSL
        }
    }
}

