                float height : TEXCOORD3;
            };

            CBUFFER_START(UnityPerMaterial)
                float4 _GrassColor;
                float _GrassHeight;
                float _GrassWidth;
                float _WindStrength;
                float _WindSpeed;
                float _Density;
            CBUFFER_END

            v2g vert(Attributes input)
            {
                v2g output;
                output.positionOS = input.positionOS;
                output.normalOS = input.normalOS;
                output.uv = input.uv;
                return output;
            }

            float3 WindOffset(float3 worldPos, float height)
            {
                float time = _Time.y * _WindSpeed;
                float noise = sin(worldPos.x * 0.5 + time) * cos(worldPos.z * 0.3 + time * 0.7);
                return float3(noise * _WindStrength * height, 0, noise * _WindStrength * height * 0.5);
            }

            [maxvertexcount(12)]
            void geom(triangle v2g input[3], inout TriangleStream<g2f> triStream)
            {
                float3 centerOS = (input[0].positionOS + input[1].positionOS + input[2].positionOS) / 3.0;
                float3 centerWS = TransformObjectToWorld(centerOS);
                float3 normalWS = TransformObjectToWorldNormal(input[0].normalOS);

                // Generate multiple grass blades per triangle
                for (int i = 0; i < _Density; i++)
                {
                    float angle = (i / _Density) * PI * 2.0;
                    float radius = 0.3;
                    float2 offset = float2(cos(angle), sin(angle)) * radius;

                    float3 basePosWS = centerWS + float3(offset.x, 0, offset.y);
                    float3 wind = WindOffset(basePosWS, 1.0);

                    float3 topPosWS = basePosWS + normalWS * _GrassHeight + wind;
                    float3 leftPosWS = basePosWS - float3(_GrassWidth, 0, 0);
                    float3 rightPosWS = basePosWS + float3(_GrassWidth, 0, 0);

                    g2f o1, o2, o3;
                    o1.positionCS = TransformWorldToHClip(leftPosWS);
                    o1.positionWS = leftPosWS;
                    o1.normalWS = normalWS;
                    o1.uv = float2(0, 0);
                    o1.height = 0;

                    o2.positionCS = TransformWorldToHClip(rightPosWS);
                    o2.positionWS = rightPosWS;
                    o2.normalWS = normalWS;
                    o2.uv = float2(1, 0);
                    o2.height = 0;

                    o3.positionCS = TransformWorldToHClip(topPosWS);
                    o3.positionWS = topPosWS;
                    o3.normalWS = normalize(normalWS + wind * 0.5);
                    o3.uv = float2(0.5, 1);
                    o3.height = 1;

                    triStream.Append(o1);
                    triStream.Append(o2);
                    triStream.Append(o3);
                    triStream.RestartStrip();
                }
            }

            float4 frag(g2f input) : SV_Target
            {
                float3 color = lerp(_GrassColor.rgb * 0.7, _GrassColor.rgb, input.height);
                float3 normalWS = normalize(input.normalWS);
                float NdotL = saturate(dot(normalWS, normalize(_MainLightPosition.xyz)));
                color *= NdotL;
                return float4(color, 1.0);
            }
            ENDHLSL
        }
    }
}

using Unity.Netcode;
using UnityEngine;
using System;

// ============================================
// NETWORK MANAGER CONFIGURATION
// ============================================
public class GameNetworkManager : NetworkBehaviour
{
    public static GameNetworkManager Instance { get; private set; }

    [SerializeField] private NetworkObject playerPrefab;
    [SerializeField] private Transform[] spawnPoints;
    [SerializeField] private int maxPlayers = 8;

    private NetworkList<PlayerData> connectedPlayers;
    public event Action<ulong> OnPlayerConnected;
    public event Action<ulong> OnPlayerDisconnected;

    void Awake()
    {
        Instance = this;
        connectedPlayers = new NetworkList<PlayerData>();
    }

    public override void OnNetworkSpawn()
    {
        if (IsServer)
        {
            NetworkManager.Singleton.OnClientConnectedCallback += OnClientConnected;
            NetworkManager.Singleton.OnClientDisconnectCallback += OnClientDisconnected;
        }
    }

    public override void OnNetworkDespawn()
    {
        if (IsServer)
        {
            NetworkManager.Singleton.OnClientConnectedCallback -= OnClientConnected;
            NetworkManager.Singleton.OnClientDisconnectCallback -= OnClientDisconnected;
        }
    }

    private void OnClientConnected(ulong clientId)
    {
        if (connectedPlayers.Count >= maxPlayers)
        {
            NetworkManager.Singleton.DisconnectClient(clientId);
            return;
        }

        SpawnPlayer(clientId);
        connectedPlayers.Add(new PlayerData
        {
            ClientId = clientId,
            PlayerName = $"Player_{clientId}",
            TeamId = (int)(clientId % 2),
            IsReady = false
        });

        OnPlayerConnected?.Invoke(clientId);
    }

    private void OnClientDisconnected(ulong clientId)
    {
        // Find and remove player data
        for (int i = 0; i < connectedPlayers.Count; i++)
        {
            if (connectedPlayers[i].ClientId == clientId)
            {
                connectedPlayers.RemoveAt(i);
                break;
            }
        }

        // Despawn player object
        if (NetworkManager.Singleton.ConnectedClients.TryGetValue(clientId, out var client))
        {
            if (client.PlayerObject != null)
            {
                client.PlayerObject.Despawn(true);
            }
        }

        OnPlayerDisconnected?.Invoke(clientId);
    }

    private void SpawnPlayer(ulong clientId)
    {
        int spawnIndex = (int)(clientId % (ulong)spawnPoints.Length);
        Vector3 spawnPos = spawnPoints[spawnIndex].position;

        NetworkObject playerInstance = Instantiate(playerPrefab, spawnPos, Quaternion.identity);
        playerInstance.SpawnAsPlayerObject(clientId);

        // Initialize player on all clients
        var playerController = playerInstance.GetComponent<PlayerNetworkController>();
        playerController.Initialize(clientId);
    }

    [ServerRpc(RequireOwnership = false)]
    public void SetPlayerReadyServerRpc(ulong clientId, bool isReady)
    {
        for (int i = 0; i < connectedPlayers.Count; i++)
        {
            if (connectedPlayers[i].ClientId == clientId)
            {
                var playerData = connectedPlayers[i];
                playerData.IsReady = isReady;
                connectedPlayers[i] = playerData;
                break;
            }
        }

        CheckAllPlayersReady();
    }

    private void CheckAllPlayersReady()
    {
        if (connectedPlayers.Count == 0) return;

        bool allReady = true;
        foreach (var player in connectedPlayers)
        {
            if (!player.IsReady)
            {
                allReady = false;
                break;
            }
        }

        if (allReady)
        {
            StartGameClientRpc();
        }
    }

    [ClientRpc]
    private void StartGameClientRpc()
    {
        Debug.Log("Game starting!");
        // Transition to gameplay on all clients
    }
}

public struct PlayerData : INetworkSerializable
{
    public ulong ClientId;
    public FixedString32Bytes PlayerName;
    public int TeamId;
    public bool IsReady;

    public void NetworkSerialize<T>(BufferSerializer<T> serializer) where T : IReaderWriter
    {
        serializer.SerializeValue(ref ClientId);
        serializer.SerializeValue(ref PlayerName);
        serializer.SerializeValue(ref TeamId);
        serializer.SerializeValue(ref IsReady);
    }
}

using Unity.Netcode;
using UnityEngine;

public class PlayerNetworkController : NetworkBehaviour
{
    [SerializeField] private float moveSpeed = 5f;
    [SerializeField] private float rotationSpeed = 10f;

    private NetworkVariable<Vector3> networkPosition = new NetworkVariable<Vector3>(
        readPerm: NetworkVariableReadPermission.Everyone,
        writePerm: NetworkVariableWritePermission.Server
    );

    private NetworkVariable<Quaternion> networkRotation = new NetworkVariable<Quaternion>(
        readPerm: NetworkVariableReadPermission.Everyone,
        writePerm: NetworkVariableWritePermission.Server
    );

    private Vector3 predictedPosition;
    private Quaternion predictedRotation;
    private Vector3 serverPosition;
    private float reconciliationSpeed = 10f;
    private bool isPredicting;

    void Start()
    {
        predictedPosition = transform.position;
        predictedRotation = transform.rotation;
    }

    public override void OnNetworkSpawn()
    {
        networkPosition.OnValueChanged += OnPositionChanged;
        networkRotation.OnValueChanged += OnRotationChanged;
    }

    void Update()
    {
        if (IsOwner)
        {
            // Client prediction: process input immediately
            Vector3 input = new Vector3(Input.GetAxis("Horizontal"), 0, Input.GetAxis("Vertical"));

            if (input.magnitude > 0.01f)
            {
                Vector3 moveDir = input.normalized;
                predictedPosition += moveDir * moveSpeed * Time.deltaTime;
                predictedRotation = Quaternion.Slerp(predictedRotation, Quaternion.LookRotation(moveDir), rotationSpeed * Time.deltaTime);

                // Send input to server
                MoveServerRpc(input, Time.time);
                isPredicting = true;
            }

            // Reconcile with server authority
            if (isPredicting)
            {
                float distance = Vector3.Distance(predictedPosition, serverPosition);
                if (distance > 0.5f)
                {
                    // Snap if too far (teleport/desync)
                    predictedPosition = serverPosition;
                }
                else
                {
                    // Smooth reconciliation
                    predictedPosition = Vector3.Lerp(predictedPosition, serverPosition, reconciliationSpeed * Time.deltaTime);
                }
            }

            transform.position = predictedPosition;
            transform.rotation = predictedRotation;
        }
        else if (!IsOwner && !IsServer)
        {
            // Interpolate remote players
            transform.position = Vector3.Lerp(transform.position, networkPosition.Value, 10f * Time.deltaTime);
            transform.rotation = Quaternion.Slerp(transform.rotation, networkRotation.Value, 10f * Time.deltaTime);
        }
    }

    [ServerRpc]
    private void MoveServerRpc(Vector3 input, float clientTime)
    {
        // Server authority: validate and apply
        Vector3 moveDir = input.normalized;
        Vector3 newPosition = transform.position + moveDir * moveSpeed * Time.deltaTime;
        Quaternion newRotation = Quaternion.LookRotation(moveDir);

        // Anti-cheat: clamp speed
        float maxDistance = moveSpeed * 1.2f * Time.deltaTime;
        if (Vector3.Distance(transform.position, newPosition) > maxDistance)
        {
            // Reject — client is cheating or desynced
            newPosition = transform.position;
        }

        networkPosition.Value = newPosition;
        networkRotation.Value = newRotation;
    }

    private void OnPositionChanged(Vector3 previous, Vector3 current)
    {
        if (IsOwner)
        {
            serverPosition = current;
        }
    }

    private void OnRotationChanged(Quaternion previous, Quaternion current) { }

    public void Initialize(ulong clientId)
    {
        // Set player color, name, etc.
    }
}
